DELETE FROM "model"  WHERE formid = 'PAYROLL_STARTER_FORM';
DELETE FROM "modelfield"  WHERE form_id = 'PAYROLL_STARTER_FORM';




UPDATE modelfield set sectionStyle  = 'slideDown-box  group expand hideCustomField' WHERE form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set fieldSetStyle = 'slideDown-content group labelLine' WHERE form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set fieldSetStyle = 'slideDown-content group nobrd' WHERE noLabelFor is not null AND noLabelFor != '' AND form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set halfSetStyle = 'halfSet-1 left' WHERE form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set halfSetStyle = '' WHERE noLabelFor is not null AND noLabelFor != '' AND form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set rowStyle = 'row hideCustomField' WHERE form_id = 'PAYROLL_STARTER_FORM';
UPDATE modelfield set fieldStyle = 'field' WHERE form_id = 'PAYROLL_STARTER_FORM';

UPDATE company SET isdeleted = FALSE WHERE isdeleted IS NULL AND (SELECT "anv".convertCustomFieldsToModelFields('PAYROLL_STARTER_FORM', 'addpaymentcategory')) IS NOT NULL;